PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE,hash TEXT,recovery TEXT,name TEXT NOT NULL DEFAULT 'Visitante',photo TEXT DEFAULT '',prefs TEXT DEFAULT '{}');
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user TEXT REFERENCES users ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS chats(id TEXT PRIMARY KEY,user TEXT NOT NULL REFERENCES users ON DELETE CASCADE,title TEXT NOT NULL,pinned INTEGER DEFAULT 0,updated INTEGER NOT NULL,messages TEXT NOT NULL DEFAULT '[]',model TEXT DEFAULT '');
CREATE INDEX IF NOT EXISTS chat_owner ON chats(user, updated);
